rule.definition:
/*IF true is returned this means validations are met */
if(
  /*US FORM AND SAVE EXIT*/
  ri!button = #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155714",
  and(
    /*Type of Position */
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.positionTypeId),
    /*Sub-type of Position*/
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.subPositionTypeId),
    /*sub-position non-traditional*/
    if(
        and(ri!nomination.subPositionTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599223",
        toboolean(ri!isOldVersion)=false),
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.nonTraditionalTypeId),
        true


    ),
    /*sub-postion non-trad others*/
    if(and(
      ri!nomination.positionTypeId=150,
        ri!nomination.subPositionTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599223",
        ri!nomination.nonTraditionalTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599217",
        toboolean(ri!isOldVersion)=false),
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherNonTraditionalRotationType),

true

    ),
    /*Candidate Selection*/
    if(
      and(
        ri!nomination.isDirectHire = true,
        ri!nomination.isDirectHireInternal = false
      ),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.firstName),
      true
    ),
    if(
      and(
        ri!nomination.isDirectHire = true,
        ri!nomination.isDirectHireInternal = false
      ),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.lastName),
      true
    ),
    if(
      ri!nomination.isDirectHire = true, 
      true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.employeeId)
    ),
     /*CANDIDATE FIELDS*/
    if(
      ri!nomination.isDirectHire = true, 
      true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.functionName)
    ),
    if(
      ri!nomination.isDirectHire = true, 
      true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.levelName)
    ),
    if(
      ri!nomination.isDirectHire = true, 
      true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.jobDescription)
    ),
    if(
      ri!nomination.isDirectHire = true, 
      true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.currentPML)
    ),
    if(
      ri!nomination.isDirectHire = true,
      true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingBU)
    ),
    if(
      and(ri!nomination.isDirectHire = true,
      ri!isOldVersion=true
      ),

      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingRegion),
      true
    ),
    if(
      ri!nomination.isDirectHire = true,
      true,
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingHomeOffice)
    ),
    if(
      ri!nomination.originatingBU = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherOriginatingBU),
      true
    ),
    if(
      and(ri!nomination.originatingRegion = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
      ri!isOldVersion=true),
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherOriginatingRegion),

      true
    ),
    if(
      ri!nomination.originatingHomeOffice = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherOriginatingHomeOffice),
      true
    ),
    /*  Future partner promote    */
    /*if(*/
      /*ri!isOldVersion<>true,*/
/**/
      /*rule!APN_isNotBlank(ri!nomination.isFuturePartnerPromote),*/
      /*true*/
    /*)*/
  ),
  if(
    /*US FORM AND SUBMIT */
    ri!button = #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
    and(
      /*--------------------------CANDIDATE SELECTION---------------------------------------------*/
      /*IS CANDIDATE DIRECT HIRE*/
      /*Type of Position */
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.positionTypeId),
      /*Sub-type of Position*/
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.subPositionTypeId),
      /*sub-position non-traditional*/
      if(
        and(ri!nomination.subPositionTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599223",
        toboolean(ri!isOldVersion)=false),
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.nonTraditionalTypeId),
        true


      ),
      /*sub-postion non-trad others*/
      if(and(
        ri!nomination.positionTypeId=150,
        ri!nomination.subPositionTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599223",
        ri!nomination.nonTraditionalTypeId = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599217",
        toboolean(ri!isOldVersion)=false),
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherNonTraditionalRotationType),

        true

      ),
      /*Candidate Selection*/
      if(
        and(
          ri!nomination.isDirectHire = true,
          ri!nomination.isDirectHireInternal = false
        ),
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.firstName),
        true
      ),
      if(
        and(
          ri!nomination.isDirectHire = true,
          ri!nomination.isDirectHireInternal = false
        ),
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.lastName),
        true
      ),
      if(
        ri!nomination.isDirectHire = true, 
        true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.employeeId)
      ),
      /*CANDIDATE FIELDS*/
      if(
        ri!nomination.isDirectHire = true, 
        true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.functionName)
      ),
      if(
        ri!nomination.isDirectHire = true, 
        true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.levelName)
      ),
      if(
        ri!nomination.isDirectHire = true, 
        true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.jobDescription)
      ),
      if(
        ri!nomination.isDirectHire = true, 
        true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.currentPML)
      ),
      if(
        ri!nomination.isDirectHire = true,
        true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingBU)
      ),
      if(
        and(ri!nomination.isDirectHire = true,
        ri!isOldVersion=true
        ),

        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingRegion),
        true
      ),
      if(
        ri!nomination.isDirectHire = true,
        true,
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.originatingHomeOffice)
      ),
      if(
        ri!nomination.originatingBU = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherOriginatingBU),
        true
      ),
      if(
        and(ri!nomination.originatingRegion = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
        ri!isOldVersion=true),
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherOriginatingRegion),
        true
      ),
      if(
        ri!nomination.originatingHomeOffice = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherOriginatingHomeOffice),
        true
      ),
      /*------------------Candidate further details---------------------------------------*/
      /*RETURNING REGION */
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          or(
            index(ri!nomination,"subPositionTypeId",tointeger(null)) = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
            index(ri!nomination,"positionTypeId",tointeger(null)) = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
          ),
          if(ri!isOldVersion=true,
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.returnRegion),true),
          true
        )
      ),
      /*RETURNING BU*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            or(
              index(ri!nomination,"subPositionTypeId",tointeger(null)) = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
              index(ri!nomination,"positionTypeId",tointeger(null)) = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
            ),
            not(property(ri!nomination,"isDirectHire",toboolean(null)) = true),
            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!nomination.otherReturningBU)
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.returnBU),
          true
        )
      ),
      /*RETURNING HOME OFFICE*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            or(
              index(ri!nomination,"subPositionTypeId",tointeger(null)) = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
              index(ri!nomination,"positionTypeId",tointeger(null)) = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
            ),
            not(property(ri!nomination,"isDirectHire",toboolean(null)) = true)
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.returnHomeOffice),
          true
        )
      ),
      /*EXPECTED MD PROMOTION DATE*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            property(ri!nomination,"positionTypeId",tointeger(null))<>#"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596124",
            property(ri!nomination,"subPositionTypeId",tointeger(null))<>#"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
            property(ri!nomination,"subPositionTypeId",tointeger(null))<>#"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148695"
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.mdPromotionDate),
          true
        )
      ),
      /*RATIONALE FOR NOMINATION*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            or(
              index(ri!nomination,"positionTypeId",tointeger(null)) = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692",
              index(ri!nomination,"positionTypeId",tointeger(null)) = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
            ),
            not(property(ri!nomination,"isDirectHire",toboolean(null)) = true)
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.rationalForNomination),
          true
        )
      ),
      /*YEARS WITH FIRM*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          or(
            property(ri!nomination,"isDirectHire",null) = false,
            #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(ri!nomination,"isDirectHire",null))
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.yearsWithFirm),
          true
        )
      ),
      /*OTHER - RETURNING BU*/
      if(
        ri!nomination.returnBU = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherReturningBU),
        true
      ),
      /*OTHER RETURNING REGION*/
      if(
        and(ri!nomination.returnRegion = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",ri!isOldVersion=true),
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherReturningRegion),
        true
      ),
      /*OTHER RETURNING HOME OFFICE*/
      if(
        ri!nomination.returnHomeOffice = #"_a-0000e6c1-137f-8000-9bf9-011c48011c48_3565630",
        #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.otherReturningHomeOffice),
        true
      ),
      /*EXPECTED PARTNER PROMOTION DATE*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            property(ri!nomination,"positionTypeId",tointeger(null))<>#"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596124",
            property(ri!nomination,"subPositionTypeId",tointeger(null))<>#"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
            property(ri!nomination,"isDirectHire",null) <> true,

          ),
          if(ri!isOldVersion=true,#"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.partnerPromotionDate),true),
          true
        )
      ),

      /*  Future partner promote    */
      /*if(*/
        /*ri!isOldVersion<>true,*/
/**/
        /*rule!APN_isNotBlank(ri!nomination.isFuturePartnerPromote),*/
        /*true*/
      /*),*/
      /*------------------------ROLE--------------------------------------------------*/
      /*ANTICIPATED START DATE*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          not(property(ri!nomination,"isDirectHire",toboolean(null)) = true),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.anticipatedStartDate),
          true
        )
      ),
      /*ANTICIPATED END DATE*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          or(
            index(ri!nomination,"subPositionTypeId",tointeger(null)) = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895",
            index(ri!nomination,"positionTypeId",tointeger(null)) = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699"
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.anticipatedEndDate),
          true
        )
      ),
      /*RECOMMENDED GROUP*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            not(property(ri!nomination,"isDirectHire",toboolean(null)) = true),
            property(ri!nomination,"positionTypeId",null) = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692"
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.recommendedDppGroupId),
          true
        )
      ),
      /*OTHER - RECOMMENDED GROUP*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            property(ri!nomination, "isDirectHire", null) = false,
            property(ri!nomination, "positionTypeId", null) = #"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596692",
            or(
              property(
                ri!nomination,
                "recommendedDppGroupId",
                null
              ) = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3827970",
              property(
                ri!nomination,
                "recommendedDppGroupId",
                null
              ) = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11635234"
            )
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.dppGroupOtherComment),
          true
        )
      ),
      /*IS POTENTIAL SEC, FASB, GASB*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            property(ri!nomination,"positionTypeId",tointeger(null))=#"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
            property(ri!nomination,"isDirectHire",null) = false
          ),
          if(ri!isOldVersion=true,
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isPotentialSec_FasbCandidate),
          true),
          true
        )
      ),
      /*IS AQS*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          and(
            property(ri!nomination,"positionTypeId",tointeger(null))=#"_a-0000e6c6-37ec-8000-9bfb-011c48011c48_3596699",
            property(ri!nomination,"isDirectHire",null) = false
          ),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.isAqspNomination),
          true
        )
      ),
      /*PRIMARY INDUSTRY*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          not(property(ri!nomination,"isDirectHire",toboolean(null)) = true),
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.primaryIndustryId),
          true
        )
      ),
      /*OTHER - PRIMARY INDUSTRY*/
      if(
        ri!nomination.isDirectHire = true,
        true,
        if(
          ri!nomination.primaryIndustryId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4149854",
          #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!nomination.primaryIndustryOther),
          true
        )
      ),
      /*DOCUMENTS*/
      if(
        or(
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(ri!taskStatus),
          contains(
            {
              #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4570051",
              #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4570066",
            },
            ri!taskStatus
          )
        ),
        if(
          ri!nomination.isDirectHire,
          true,
          ri!hasDocument
        ),
        true
      )
    ),
    false
  )
)
